		fmt.Println(letters[i])
	}

	fmt.Println("Multiples of 3:")
	for _, n := range nums {
		if n%3 != 0 {
			continue
		}
		fmt.Println(n)
	}
}

steps.body:
To walk a slice backwards, start at the last index and count down while the index is still valid.

```go harness
package main

import "fmt"

func main() {
	s := []string{"one", "two", "three", "four"}
	{{code}}
}
```

```go
for i := len(s) - 1; i >= 0; i-- {
	fmt.Println(s[i])
}
```

Start at `len(s) - 1`, not `len(s)`, which is one past the end and panics. Use `i >= 0` so index 0 is included. For an empty slice the start is -1, so the body never runs.

To reverse a slice *in place*, walk two indexes toward each other and swap as you go. A `for` header can declare and update two variables at once with multiple assignment.

```go harness
package main

import "fmt"

func main() {
	s := []int{1, 2, 3, 4, 5}
	{{code}}
	fmt.Println(s)
}
```

```go
for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
	s[i], s[j] = s[j], s[i]
}
```

The swap needs no temporary variable because the right side is evaluated before anything is assigned. The loop stops when the indexes meet, so each pair swaps exactly once and the middle of an odd length stays put. Using `i < len(s)` instead would swap everything twice and undo the work.

In place means no new slice is made: the swaps rewrite the elements the slice already holds. Assigning a slice shares its elements, so any other variable you assigned it to sees the reversed order too.

example.code:
package main

import "fmt"

func main() {
	words := []string{"one", "two", "three", "four"}
	for i := len(words) - 1; i >= 0; i-- {
		fmt.Println(words[i])
	}

	nums := []int{1, 2, 3, 4, 5}
	for i, j := 0, len(nums)-1; i < j; i, j = i+1, j-1 {
		nums[i], nums[j] = nums[j], nums[i]
	}
	fmt.Println(nums)
}

