package main

import "fmt"

func main() {
	temps := []int{-3, 5, 0, 12, -8, 7}

	var above []int
	var freezing []int
	var boiling []int
	for _, t := range temps {
		if t > 0 {
			above = append(above, t)
		} else {
			freezing = append(freezing, t)
		}
		if t >= 100 {
			boiling = append(boiling, t)
		}
	}

	fmt.Println("Above:", above)
	fmt.Println("Freezing:", freezing)
	if len(boiling) == 0 {
		fmt.Println("None boiling")
	} else {
		fmt.Println("Boiling:", boiling)
	}
	fmt.Println("All:", temps)
}

